select throws_ok($$delete from storage.objects where bucket_id='household-files' and name='00000100-0000-4000-8000-000000000301/documents/00000700-0000-4000-8000-000000000004.pdf'$$,'42501',null,'object deletion must use the Storage API');
select lives_ok($$select public.finish_household_attachment_cleanup('00000100-0000-4000-8000-000000000301/documents/00000700-0000-4000-8000-000000000004.pdf')$$,'cleanup completion safely tolerates an object still present');
select is((select state from public.household_attachment_uploads where path='00000100-0000-4000-8000-000000000301/documents/00000700-0000-4000-8000-000000000004.pdf'),'deleting','cleanup does not claim deletion before the object is gone');
select throws_ok($$insert into public.household_documents(id,household_id,created_by,title,file_path) values ('00000800-0000-4000-8000-000000000004','00000100-0000-4000-8000-000000000301','00000000-0000-4000-8000-000000000301','Document','00000100-0000-4000-8000-000000000301/documents/00000700-0000-4000-8000-000000000004.pdf')$$,'22023',null,'cleanup-owned file remains unavailable while deletion is pending');
select lives_ok($$select * from public.begin_household_attachment_cleanup('00000100-0000-4000-8000-000000000301/documents/00000700-0000-4000-8000-000000000003.pdf')$$,'cleanup acquires the reservation with no uploaded object');
select lives_ok($$select public.finish_household_attachment_cleanup('00000100-0000-4000-8000-000000000301/documents/00000700-0000-4000-8000-000000000003.pdf')$$,'cleanup completes when the object is absent');
select is((select state from public.household_attachment_uploads where path='00000100-0000-4000-8000-000000000301/documents/00000700-0000-4000-8000-000000000003.pdf'),'deleted','absent object leaves a permanent deletion tombstone');
select throws_ok($$update public.household_documents set file_path='00000100-0000-4000-8000-000000000301/documents/00000700-0000-4000-8000-000000000003.pdf' where id='00000800-0000-4000-8000-000000000001'$$,'22023',null,'deleted file cannot be claimed again');
select throws_ok($$insert into public.household_documents(id,household_id,created_by,title,file_path) values ('00000800-0000-4000-8000-000000000005','00000100-0000-4000-8000-000000000301','00000000-0000-4000-8000-000000000301','Document','00000100-0000-4000-8000-000000000301/documents/00000700-0000-4000-8000-000000000005.pdf')$$,'22023',null,'unregistered paths do not masquerade as documents');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000302',true);
select lives_ok($$insert into public.household_documents(id,household_id,title,file_path) values ('00000800-0000-4000-8000-000000000002','00000100-0000-4000-8000-000000000301','Shared original','00000100-0000-4000-8000-000000000301/documents/00000700-0000-4000-8000-000000000001.pdf')$$,'partner may reference an already claimed household document');
select is(public.read_household_cost_context('asset','00000200-0000-4000-8000-000000000302')->>'paid_cents','5000','partner sees the same derived costs');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000303',true);
select throws_ok($$select public.read_household_cost_context('project','00000200-0000-4000-8000-000000000301')$$,'42501',null,'outsider cannot read context totals or lineage');
select throws_ok($$select public.read_household_cost_context('project','00000200-0000-4000-8000-000000000998')$$,'42501',null,'missing context uses the same unavailable response');
select is((select count(*) from public.household_documents),0::bigint,'outsider cannot read household documents');
select throws_ok($$insert into public.household_documents(household_id,title,file_path) values ('00000100-0000-4000-8000-000000000301','Foreign document','00000100-0000-4000-8000-000000000301/documents/00000700-0000-4000-8000-000000000001.pdf')$$,'42501',null,'outsider cannot claim another household file');
select throws_ok($$select private.claim_household_attachment('00000100-0000-4000-8000-000000000301/documents/00000700-0000-4000-8000-000000000001.pdf','00000100-0000-4000-8000-000000000301')$$,'42501',null,'direct private claim helper is not callable');
select is((select count(*) from storage.objects where bucket_id='household-files' and name='00000100-0000-4000-8000-000000000301/documents/00000700-0000-4000-8000-000000000001.pdf'),0::bigint,'outsider cannot read private storage metadata');
reset role;
set local role anon;
select set_config('request.jwt.claim.sub','',true);
select throws_ok($$select public.read_household_cost_context('project','00000200-0000-4000-8000-000000000301')$$,'42501',null,'anonymous cost RPC access denied');
select throws_ok($$select * from public.household_documents$$,'42501',null,'anonymous document reads denied');
